try {
  const res = await fetch(`${baseUrl}/rest/v1/rpc/bt_current_user_plan`, {
    method: 'POST',
    headers: { apikey: anonKey, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: '{}',
  })
  if (!res.ok) return { plan: applyPlan('free'), error: res.status }
